// Küçük çoklu grafiklerin saf mantığı: büyüme, trend, sıralama, ölçek ve yazımlar. Sayılar ve tarihler ABACUS'tandır.
import { collate, date, math, money } from "@snn/abacus-core";

export interface MultiSeries { key: string; label: string; /** Dönem sırasıyla değerler (periods ile aynı uzunlukta). */ values: number[] }
export type SortMode = "last" | "growth" | "name";
export type ScaleMode = "independent" | "shared";
export type Trend = "up" | "flat" | "down" | "none";

/** Geçen yıla göre büyüme yüzdesi: `index` ayı ile `lookback` ay öncesi; geçmiş yoksa ya da taban sıfırsa null. */
export function growthAt(values: number[], index: number, lookback = 12): number | null {
  const base = values[index - lookback], now = values[index];
  if (base === undefined || now === undefined || base === 0) return null;
  return math.percentChange(now, base);
}

/** Trend: büyüme eşiğin (yüzde) altındaysa düz. */
export function trendOf(growth: number | null, flatBelow = 2): Trend {
  if (growth === null) return "none";
  return Math.abs(growth) < flatBelow ? "flat" : growth > 0 ? "up" : "down";
}

export const trendWord = (trend: Trend) => trend === "up" ? "Yükseliyor" : trend === "down" ? "Düşüyor" : trend === "flat" ? "Düz" : "Yeterli geçmiş yok";
export const trendArrow = (trend: Trend) => trend === "up" ? "▲" : trend === "down" ? "▼" : trend === "flat" ? "▬" : "";

/** Büyüme metni: "+%12,3" (gerçek eksi işaretiyle "-%4,0"); yoksa "—". */
export const growthText = (growth: number | null) => growth === null ? "—" : money.percent(growth, 1, { sign: "always" });

/** Panelleri sıralar: son değer (büyükten küçüğe), büyüme (büyükten küçüğe, büyümesizler sonda), ad (Türkçe sıra). */
export function sortSeries<T extends MultiSeries>(series: T[], mode: SortMode, index: number, lookback = 12): T[] {
  const copy = [...series];
  if (mode === "name") return collate.sortBy(copy, item => item.label);
  if (mode === "growth") return copy.sort((a, b) => (growthAt(b.values, index, lookback) ?? -Infinity) - (growthAt(a.values, index, lookback) ?? -Infinity));
  return copy.sort((a, b) => (b.values[index] ?? 0) - (a.values[index] ?? 0));
}

/** Değer ekseni aralığı: bağımsız ölçekte serinin kendi aralığı (iki yanda %10 pay), ortak ölçekte hepsi sıfırdan en büyük değere. */
export function domainFor(series: MultiSeries, all: MultiSeries[], mode: ScaleMode): [number, number] {
  if (mode === "shared") {
    const peak = Math.max(...all.flatMap(item => item.values), 1);
    return [0, peak];
  }
  const min = Math.min(...series.values), max = Math.max(...series.values);
  const pad = (max - min || Math.abs(max) || 1) * .1;
  return [min - pad, max + pad];
}

/** Dönemlerin toplamı: her ayda tüm serilerin toplamı. */
export const totals = (series: MultiSeries[], count: number) => Array.from({ length: count }, (_, at) => series.reduce((sum, item) => sum + (item.values[at] ?? 0), 0));

/** "2026-09" → "Eylül 2026". */
export const periodLabel = (key: string) => date.format(key, "monthYear");

/** Okuma duyurusu: "Eylül 2026: toplam ₺x, en yüksek Marmara ₺y". */
export function readingAnnouncement(label: string, total: string, top: { label: string; value: string } | null): string {
  return `${label}: toplam ${total}${top ? `, en yüksek ${top.label} ${top.value}` : ""}`;
}

.root { container-type: inline-size; display: grid; min-width: 0; gap: var(--space-4); padding: var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); color: var(--foreground); }
.title { margin: 0; font-family: var(--font-display); font-size: var(--text-xl); font-weight: 500; letter-spacing: var(--tracking-display); }
.subtitle { margin: 2px 0 0; color: var(--text-secondary); font-size: var(--text-sm); }
.controls { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-3) var(--space-5); }
.reading { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--space-2) var(--space-5); min-height: 1.75rem; }
.readingMonth { color: var(--text-secondary); font-size: var(--text-sm); }
.readingTotal { font-family: var(--font-display); font-size: var(--text-xl); letter-spacing: var(--tracking-display); font-variant-numeric: tabular-nums; }
.key { display: inline-flex; align-items: center; gap: var(--space-2); color: var(--text-secondary); font-size: var(--text-xs); }
.keyLine, .keyTrace { display: inline-block; width: 1.25rem; height: 0; border-top: 2px solid var(--accent); }
.keyTrace { border-top-style: dashed; border-top-color: var(--text-muted); border-top-width: 1.5px; }
.grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-3); border-radius: var(--radius-control); outline: none; }
.grid:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: var(--focus-outline-offset, 2px); }
.panel { display: grid; gap: var(--space-2); min-width: 0; padding: var(--space-3); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-raised); transition: opacity var(--duration-standard) var(--ease-standard); }
.panel[data-flat] { opacity: .5; }
.panelHead { display: grid; gap: 1px; min-width: 0; }
.name { margin: 0; overflow: hidden; color: var(--text-secondary); font-size: var(--text-sm); font-weight: 400; text-overflow: ellipsis; white-space: nowrap; }
.value { font-family: var(--font-display); font-size: var(--text-lg); letter-spacing: var(--tracking-display); font-variant-numeric: tabular-nums; }
.growth { color: var(--text-secondary); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.growth[data-trend="up"] { color: var(--success); }
.growth em { font-style: normal; }
.chart { position: relative; height: 4.5rem; touch-action: pan-y; cursor: crosshair; }
.svg { display: block; width: 100%; height: 100%; overflow: hidden; }
.trace { fill: none; stroke: var(--text-muted); stroke-width: 1; stroke-dasharray: 3 3; vector-effect: non-scaling-stroke; opacity: .7; }
.line { fill: none; stroke: var(--accent); stroke-width: 2; stroke-linejoin: round; vector-effect: non-scaling-stroke; transition: d var(--duration-considered) var(--ease-standard); }
.axisTop, .axisBottom { position: absolute; right: 0; padding-left: 2px; background: var(--surface-raised); color: var(--text-muted); font-size: 10px; line-height: 1; pointer-events: none; }
.axisTop { top: 0; }
.axisBottom { bottom: 0; }
.cursor { position: absolute; top: 0; bottom: 0; width: 1px; background: var(--border-strong); pointer-events: none; transition: left var(--duration-fast) var(--ease-standard); }
.dot { position: absolute; width: 7px; height: 7px; margin: -3.5px 0 0 -3.5px; border: 2px solid var(--surface-raised); border-radius: 50%; background: var(--accent); pointer-events: none; transition: left var(--duration-fast) var(--ease-standard), top var(--duration-considered) var(--ease-standard); box-sizing: content-box; }
.hint { margin: 0; color: var(--text-muted); font-size: var(--text-xs); }
.empty { margin: 0; padding: var(--space-8) 0; color: var(--text-muted); text-align: center; }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
@container (max-width: 640px) { .grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } .root { padding: var(--space-4); } }
.root[data-reduced] .line, .root[data-reduced] .cursor, .root[data-reduced] .dot, .root[data-reduced] .panel { transition: none; }
@media (prefers-reduced-motion: reduce) { .line, .cursor, .dot, .panel { transition: none; } }

"use client";

import { useId, useMemo, useState, type KeyboardEvent, type PointerEvent } from "react";
import { motion } from "motion/react";
import { miniLinePath } from "../lib/chart-format";
import { metricShortText, metricValueText, type MetricKind } from "../lib/metric-format";
import { clamp, useReducedMotionSafe } from "../lib/viz-utils";
import SegmentedControl from "../segmented-control/segmented-control";
import { Skeleton } from "../skeleton/skeleton";
import { Switch } from "../switch/switch";
import { domainFor, growthAt, growthText, periodLabel, readingAnnouncement, sortSeries, totals, trendArrow, trendOf, trendWord, type MultiSeries, type ScaleMode, type SortMode } from "./small-multiples-format";
import styles from "./small-multiples.module.css";

export type { MultiSeries };
export interface MultiPeriod { /** Ay anahtarı: "2026-09". */ key: string; /** Verilmezse ABACUS `date.format` ile "Eylül 2026". */ label?: string | undefined }

/** Aynı ölçünün birkaç serisini (bölge, ürün, plan) küçük çizgi grafiklerde, ortak bir dikey imleçle yan yana karşılaştırmak için kullanın; iki üç seri tek çizimde karşılaştırılacaksa çizgi grafik daha doğrudur. */
export interface SmallMultiplesProps {
  periods: MultiPeriod[];
  series: MultiSeries[];
  title?: string | undefined;
  /** Alt satır: ölçü ve dönem aralığı, örneğin "Aylık ciro · Ekim 2025 – Eylül 2026". */
  subtitle?: string | undefined;
  kind?: MetricKind | undefined;
  /** Büyümenin kıyaslandığı geçmiş (ay sayısı); varsayılan 12 (geçen yıl). */
  lookback?: number | undefined;
  /** Bu yüzdenin altındaki büyüme "düz" sayılır. */
  flatBelow?: number | undefined;
  defaultSort?: SortMode | undefined;
  defaultScale?: ScaleMode | undefined;
  loading?: boolean | undefined;
  emptyText?: string | undefined;
}

const SORTS = [{ value: "last", label: "Son değer" }, { value: "growth", label: "Büyüme" }, { value: "name", label: "Ad" }];
const SCALES = [{ value: "independent", label: "Bağımsız" }, { value: "shared", label: "Ortak" }];

export function SmallMultiples({ periods, series, title = "Seri karşılaştırması", subtitle, kind = "money", lookback = 12, flatBelow = 2, defaultSort = "last", defaultScale = "independent", loading = false, emptyText = "Gösterilecek seri yok." }: SmallMultiplesProps) {
  const reduced = useReducedMotionSafe();
  const hintId = useId();
  const [sort, setSort] = useState<SortMode>(defaultSort);
  const [scale, setScale] = useState<ScaleMode>(defaultScale);
  const [dim, setDim] = useState(false);
  const [cursor, setCursor] = useState<number | null>(null);
  const [announce, setAnnounce] = useState("");
  const count = periods.length, last = count - 1;
  const at = cursor ?? last;
  const label = (index: number) => periods[index]?.label ?? periodLabel(periods[index]?.key ?? "");
  const sums = useMemo(() => totals(series, count), [series, count]);
  const ordered = useMemo(() => sortSeries(series, sort, last, lookback), [series, sort, last, lookback]);
  const sumDomain = useMemo((): [number, number] => { const min = Math.min(...sums), max = Math.max(...sums), pad = (max - min || 1) * .1; return [min - pad, max + pad]; }, [sums]);
  const sumPath = useMemo(() => miniLinePath(sums, 100, 40, 2, sumDomain[0], sumDomain[1]), [sums, sumDomain]);

  const announceAt = (index: number) => {
    const top = series.reduce<MultiSeries | null>((best, item) => !best || (item.values[index] ?? 0) > (best.values[index] ?? 0) ? item : best, null);
    setAnnounce(readingAnnouncement(label(index), metricValueText(kind, sums[index] ?? 0), top ? { label: top.label, value: metricValueText(kind, top.values[index] ?? 0) } : null));
  };
  const place = (index: number | null) => { setCursor(index); if (index !== null) announceAt(index); };
  const indexAt = (event: PointerEvent<HTMLElement>) => { const rect = event.currentTarget.getBoundingClientRect(); return clamp(Math.round(((event.clientX - rect.left) / rect.width) * last), 0, last); };
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const from = cursor ?? last;
    const next = ({ ArrowRight: from + 1, ArrowLeft: from - 1, PageUp: from + 12, PageDown: from - 12, Home: 0, End: last } as Record<string, number>)[event.key];
    if (next !== undefined) { event.preventDefault(); place(clamp(next, 0, last)); }
    else if (event.key === "Escape") { setCursor(null); setAnnounce(""); }
  };

  if (loading) return <section className={styles.root} aria-busy="true"><Skeleton label="Seriler yükleniyor" lines={6} /></section>;

  return <section className={styles.root} data-reduced={reduced || undefined} aria-label={title}>
    <header className={styles.header}><h3 className={styles.title}>{title}</h3>{subtitle && <p className={styles.subtitle}>{subtitle}</p>}</header>
    {!series.length || count < 2 ? <p className={styles.empty}>{emptyText}</p> : <>
      <div className={styles.controls}>
        <SegmentedControl label="Sıralama" value={sort} onValueChange={value => { setSort(value as SortMode); setAnnounce(`Sıralama: ${SORTS.find(item => item.value === value)?.label}`); }} options={SORTS} />
        <SegmentedControl label="Ölçek" value={scale} onValueChange={value => { setScale(value as ScaleMode); setAnnounce(`Ölçek: ${SCALES.find(item => item.value === value)?.label}`); }} options={SCALES} />
        <Switch label="Düz gidenleri sönük göster" checked={dim} onCheckedChange={value => { setDim(value); setAnnounce(value ? "Düz giden seriler sönük" : "Düz giden seriler normal"); }} />
      </div>

      <div className={styles.reading} aria-hidden="true">
        <span className={styles.readingMonth}>{cursor === null ? `Son: ${label(last)}` : label(cursor)}</span>
        <span className={styles.readingTotal}>Toplam {metricValueText(kind, sums[at] ?? 0)}</span>
        <span className={styles.key}><i className={styles.keyLine} />Seri</span><span className={styles.key}><i className={styles.keyTrace} />Toplamın izi</span>
      </div>

      <div className={styles.grid} role="group" aria-roledescription="küçük çoklu grafikler" aria-label={`${title}. Sol ve sağ ok imleci aylar arasında gezdirir, Home ve End uçlara atlar, Esc temizler.`} aria-describedby={hintId} tabIndex={0} onKeyDown={onKeyDown} onFocus={event => { if (event.currentTarget === event.target && event.currentTarget.matches(":focus-visible")) place(last); }} onBlur={event => { if (event.currentTarget === event.target) setCursor(null); }}>
        {ordered.map(item => {
          const growth = growthAt(item.values, at, lookback), trend = trendOf(growth, flatBelow);
          const [low, high] = domainFor(item, series, scale), span = high - low || 1;
          const percentX = count > 1 ? (at / last) * 100 : 0;
          const valueY = (1 - ((item.values[at] ?? low) - low) / span) * 100;
          return <motion.article key={item.key} layout={!reduced} transition={{ type: "spring", visualDuration: .38, bounce: 0 }} className={styles.panel} data-flat={(dim && trend === "flat") || undefined}>
            <div className={styles.panelHead}>
              <h4 className={styles.name} title={item.label}>{item.label}</h4>
              <span className={styles.value}>{metricShortText(kind, item.values[at] ?? 0)}</span>
              <span className={styles.growth} data-trend={trend} aria-hidden="true">{trend === "none" ? "Yeterli geçmiş yok" : <>{trendArrow(trend)} {growthText(growth)}{trend === "flat" && <em> Düz</em>}</>}</span>
            </div>
            <div className={styles.chart} onPointerMove={event => { if (event.pointerType === "mouse" || event.buttons) place(indexAt(event)); }} onPointerDown={event => place(indexAt(event))} onPointerLeave={event => { if (event.pointerType === "mouse") { setCursor(null); setAnnounce(""); } }}>
              <svg className={styles.svg} viewBox="0 0 100 40" preserveAspectRatio="none" aria-hidden="true">
                <path className={styles.trace} d={sumPath} />
                <path className={styles.line} d={miniLinePath(item.values, 100, 40, 2, low, high)} />
              </svg>
              <span className={styles.axisTop} aria-hidden="true">{metricShortText(kind, high)}</span><span className={styles.axisBottom} aria-hidden="true">{metricShortText(kind, Math.max(low, 0))}</span>
              <span className={styles.cursor} style={{ left: `${percentX}%` }} aria-hidden="true" />
              <span className={styles.dot} style={{ left: `${percentX}%`, top: `${clamp(valueY, 2, 98)}%` }} aria-hidden="true" />
            </div>
          </motion.article>;
        })}
      </div>
      <p id={hintId} className={styles.hint}>İmleç tüm panellerde aynı ayı gösterir.</p>

      <div className={styles.srOnly}><table>
        <caption>{title}, {label(at)}</caption>
        <thead><tr><th scope="col">Seri</th><th scope="col">Değer</th><th scope="col">Büyüme</th><th scope="col">Trend</th></tr></thead>
        <tbody>{ordered.map(item => { const growth = growthAt(item.values, at, lookback); return <tr key={item.key}><th scope="row">{item.label}</th><td>{metricValueText(kind, item.values[at] ?? 0)}</td><td>{growthText(growth)}</td><td>{trendWord(trendOf(growth, flatBelow))}</td></tr>; })}</tbody>
      </table></div>
      <p className={styles.srOnly} aria-live="polite" aria-atomic="true">{announce}</p>
    </>}
  </section>;
}

export default SmallMultiples;
